CREATE TRIGGER app_payload_root_app_public_stories_object_hash_insert BEFORE INSERT ON app_public_stories WHEN EXISTS(SELECT 1 FROM app_payload_uploads u JOIN app_payload_objects o ON o.hash=u.hash WHERE u.hash=NEW.object_hash AND (u.done<>1 OR o.complete<>1)) BEGIN SELECT RAISE(ABORT,'Unpublished payload reference'); END;
